-- ac-voice: Google Chrome control for opening ActiveCollab pages.
--
-- ChromeOpener (Sources/ACVoiceSystem) compiles this script once and calls its handlers through
-- handler Apple Events, so arguments never become script source. scripts/gen-applescript.sh embeds
-- this file as OpenACScript.generated.swift and runs osacompile as a syntax check. Edit this file,
-- then run the script; never edit the generated Swift file.
--
-- The script has no loops and makes no decisions. ChromeOpener reads the window state with
-- chromestate, picks the tab in Swift (ChromeTabPlan, unit tested) and then calls one action handler.
--
-- Handlers (AppleScript stores user handler names in lowercase, so call them in lowercase):
--   chromestate(secs)
--     -> {window ids, window modes, tab URLs per window, active tab index per window}, front to back
--   focustab(winID, tabIndex, targetURL, setURL, setTab, secs, doActivate)
--     -> "ok"  sets the tab URL only when setURL is true (no reload of an AC tab that already shows
--              the target), makes the tab active, raises the window
--   newtab(winID, targetURL, secs, doActivate) -> "ok"  new tab in that window
--   newwindow(targetURL, secs, doActivate)     -> "ok"  new normal (non-incognito) window
--   Every handler returns "notrunning" when Chrome is not running. The script never launches Chrome
--   (a "tell" would), ChromeOpener lets LaunchServices do that.
--
-- Rules (docs/REVIEW.md M4):
--   * Every block that talks to Chrome sits in "with timeout of secs seconds". The caller also keeps a
--     deadline of its own and falls back to NSWorkspace when the script does not answer in time.
--   * Windows are addressed by id: index references shift once a window moves to the front.
--     Chrome 158 declares the id as text. ChromeOpener passes it back in the form chromestate returned it,
--     because Chrome never matches a number against its text id (ChromeWindowID).
--   * "activate" comes last and only when doActivate is true. The caller may activate Chrome itself
--     instead (ChromeOpener.ActivationStrategy).

on chromestate(secs)
	if not (application id "com.google.Chrome" is running) then return "notrunning"
	with timeout of secs seconds
		tell application id "com.google.Chrome"
			set winIDs to id of every window
			set winModes to mode of every window
			set urlLists to URL of every tab of every window
			set activeIdx to active tab index of every window
		end tell
	end timeout
	return {winIDs, winModes, urlLists, activeIdx}
end chromestate

on focustab(winID, tabIndex, targetURL, setURL, setTab, secs, doActivate)
	if not (application id "com.google.Chrome" is running) then return "notrunning"
	with timeout of secs seconds
		tell application id "com.google.Chrome"
			tell window id winID
				if setURL then set URL of tab tabIndex to targetURL
				if setTab then set active tab index to tabIndex
				if minimized then set minimized to false
				set index to 1
			end tell
			if doActivate then activate
		end tell
	end timeout
	return "ok"
end focustab

on newtab(winID, targetURL, secs, doActivate)
	if not (application id "com.google.Chrome" is running) then return "notrunning"
	with timeout of secs seconds
		tell application id "com.google.Chrome"
			tell window id winID
				make new tab with properties {URL:targetURL}
				if minimized then set minimized to false
				set index to 1
			end tell
			if doActivate then activate
		end tell
	end timeout
	return "ok"
end newtab

on newwindow(targetURL, secs, doActivate)
	if not (application id "com.google.Chrome" is running) then return "notrunning"
	with timeout of secs seconds
		tell application id "com.google.Chrome"
			make new window with properties {mode:"normal"}
			set URL of active tab of window 1 to targetURL
			if doActivate then activate
		end tell
	end timeout
	return "ok"
end newwindow
"""#
